//go:build arm64

package floats

// The NEON kernel of CDotC (cdot.go), generated by go-asmgen (cdot_arm64_gen.go) into
// cdot_arm64.s: blocks of four complex numbers, writing the folded lanes of the two sums
// to out (out[0:2] the sum of a*b, out[2:4] the sum of a*swap(b)); the Go code does the
// last complex numbers. NEON is the ARMv8-A baseline: no gate. No kernel keeps a pointer:
// go:noescape.
//
//go:noescape
func cdotcNEON(a, b, out []float64)

func cdotc(a, b []float64) (re, im float64) {
	var out [4]float64
	cdotcNEON(a, b, out[:])
	re, im = out[0]+out[1], out[2]-out[3]
	tr, ti := cdotcTail(a, b, len(a)&^7)
	return re + tr, im + ti
}
